head.b:skin:
:root{--paper:#f7f5f0;--card:#fffefb;--ink:#1b2430;--soft:#475260;--faint:#66707c;--rule:#dcd7cb;--rule2:#b7b0a0;--accent:#0f6b66;--accent-ink:#ffffff;--mark:#ebe6d8;--warn:#8a5a00;--r:8px;--ui:'Noto Sans Arabic','Segoe UI',Tahoma,sans-serif}
html[data-theme=dark]{--paper:#14181c;--card:#1b2025;--ink:#ece8de;--soft:#b8b4a8;--faint:#989ea6;--rule:#2c333a;--rule2:#47505a;--accent:#6cc5bd;--accent-ink:#0d1517;--mark:#232a2e;--warn:#e0b45a}
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font:400 17px/1.8 var(--ui)}
a{color:var(--accent);text-underline-offset:3px}a:hover{text-decoration-thickness:2px}
h1,h2,h3,h4{font-family:var(--ui);line-height:1.5;margin:0;font-weight:700}
.wrap{width:min(1080px,100% - 32px);margin-inline:auto}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.skip{position:absolute;top:-80px;inset-inline-start:8px;background:var(--ink);color:var(--paper);padding:10px 14px;z-index:50}.skip:focus{top:8px}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
#nav-t{display:none}
/* الرأس */
.top{border-bottom:1px solid var(--rule);background:var(--paper)}
.bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;min-height:60px;gap:8px 12px}
.brand{font-size:22px;font-weight:700;color:var(--ink);text-decoration:none}
.bar-end{display:flex;gap:8px}
.btn-quiet{font:600 14px var(--ui);min-height:44px;padding:0 14px;display:inline-flex;align-items:center;background:none;color:var(--ink);border:1px solid var(--rule2);border-radius:var(--r);cursor:pointer}
.btn-quiet:hover{border-color:var(--ink)}
.nav{display:none;flex-basis:100%;flex-direction:column;padding-bottom:8px}
#nav-t:checked~.top .nav{display:flex}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;min-height:48px;display:flex;align-items:center;border-top:1px solid var(--rule)}
.nav a:hover{color:var(--accent)}
/* الرئيسية */
.hero{padding:36px 0 32px;border-bottom:1px solid var(--rule)}
.hero h1{font-size:clamp(28px,7vw,46px);line-height:1.35;max-width:18ch}
.lede{color:var(--soft);font-size:18px;max-width:56ch;margin:12px 0 22px}
.find{display:flex;max-width:640px}
.find input{flex:1;min-width:0;min-height:52px;font:400 17px var(--ui);padding:0 16px;border:1px solid var(--ink);border-inline-end:0;background:var(--card);color:var(--ink);border-start-start-radius:var(--r);border-end-start-radius:var(--r)}
.find button{min-height:52px;padding:0 22px;font:600 16px var(--ui);border:1px solid var(--accent);background:var(--accent);color:var(--accent-ink);cursor:pointer;border-start-end-radius:var(--r);border-end-end-radius:var(--r)}
.find button:hover{filter:brightness(.93)}
.sec{padding:36px 0 4px}
.sec h2{font-size:22px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px}
.tag{font:600 12px var(--ui);color:var(--warn);border:1px solid currentColor;border-radius:4px;padding:1px 8px}
.note{color:var(--soft);margin:-6px 0 14px;font-size:16px}
.topics{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.topics a{display:block;height:100%;padding:14px;background:var(--card);border:1px solid var(--rule);border-radius:var(--r);text-decoration:none;color:var(--ink)}
.topics a:hover{border-color:var(--accent)}
.topics b{display:block;font-size:16px;line-height:1.5}
.topics span{display:block;color:var(--soft);font-size:14px;line-height:1.6;margin-top:4px}
.games{list-style:none;margin:0;padding:0;border-top:2px solid var(--ink)}
.games li{display:grid;grid-template-columns:32px 1fr;gap:12px;padding:14px 0;border-bottom:1px solid var(--rule);counter-increment:g}
.games{counter-reset:g}
.games li::before{content:counter(g);font-weight:700;color:var(--accent)}
.games b{display:block;font-size:16px}.games span{color:var(--soft);font-size:15px}
.posts{list-style:none;margin:0;padding:0;border-top:2px solid var(--ink)}
.posts li{padding:16px 0;border-bottom:1px solid var(--rule)}
.posts a{font-weight:700;font-size:18px;line-height:1.6;color:var(--ink);text-decoration:none}.posts a:hover{color:var(--accent)}
.posts p{margin:4px 0 0;color:var(--soft);font-size:16px}
.meta{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:13px;color:var(--faint)}
.more{margin:14px 0 0}
.method{display:grid;gap:0;border-top:2px solid var(--ink)}
.method div{padding:16px 0;border-bottom:1px solid var(--rule)}
.method h3{font-size:17px}.method p{margin:2px 0 0;color:var(--soft);font-size:16px}
/* صفحات المحتوى */
.page{padding:24px 0}
.crumbs{font-size:13px;color:var(--faint);margin-bottom:10px}.crumbs a{color:var(--faint)}
.page h1{font-size:clamp(26px,6vw,38px);line-height:1.4;margin-bottom:10px}
.labels{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}.labels a{font-size:13px;padding:2px 10px;border:1px solid var(--rule2);border-radius:4px;color:var(--soft);text-decoration:none}
.byline{display:flex;gap:14px;flex-wrap:wrap;font-size:14px;color:var(--faint);margin-bottom:18px}
.prose{max-width:68ch}.prose h2{font-size:23px;margin:1.8em 0 .4em}.prose h3{font-size:19px;margin:1.4em 0 .3em}
.prose p,.prose li{margin:.8em 0}.prose img{max-width:100%;height:auto}
.prose table{border-collapse:collapse;width:100%;display:block;overflow-x:auto}.prose th,.prose td{border:1px solid var(--rule2);padding:8px 12px;text-align:start}
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:30px;font-weight:600}
.err{padding:56px 0;text-align:center}.err .find{margin:20px auto}.err h1{font-size:30px}
.btn{display:inline-flex;align-items:center;min-height:48px;padding:0 22px;background:var(--accent);color:var(--accent-ink);border-radius:var(--r);text-decoration:none;font-weight:600}
/* التذييل */
.foot{margin-top:56px;border-top:2px solid var(--ink);padding-top:28px;font-size:15px}
.foot-grid{display:grid;gap:24px}
.foot-brand{font-size:20px;font-weight:700}.foot p{margin:6px 0 0;color:var(--soft);max-width:36ch}
.foot h4{font-size:14px;color:var(--faint);margin-bottom:6px}
.foot ul{list-style:none;margin:0;padding:0}.foot li a{display:inline-block;padding:6px 0;color:var(--ink);text-decoration:none}.foot li a:hover{color:var(--accent);text-decoration:underline}
.foot-end{border-top:1px solid var(--rule);margin-top:24px;padding:16px 0 24px;color:var(--faint);font-size:14px}
@media(min-width:760px){
 .bar{flex-wrap:nowrap}.menu-btn{display:none}
 .nav{display:flex!important;flex-direction:row;flex-basis:auto;padding:0;gap:4px;margin-inline-start:auto;order:0}
 .nav a{border:0;min-height:44px;padding:0 12px}
 .bar-end{order:2}
 .hero{padding:64px 0 52px}
 .topics{grid-template-columns:repeat(4,1fr);gap:12px}
 .method{grid-template-columns:repeat(3,1fr);gap:24px;border-top:2px solid var(--ink)}.method div{border:0;padding:16px 0}
 .games{display:grid;grid-template-columns:1fr 1fr;column-gap:40px}
 .foot-grid{grid-template-columns:1.4fr 1fr 1fr}
}
@media print{.top,.foot,.find{display:none}}
.foot-grid ul{columns:2;column-gap:16px}
@media(min-width:760px){.foot-grid ul{columns:1}}

body.script:
//
(function(){
  var d=document.documentElement,b=document.getElementById('theme-toggle');
  function label(){if(b)b.textContent=d.getAttribute('data-theme')==='dark'?'الوضع الفاتح':'الوضع الداكن';}
  label();
  if(b)b.addEventListener('click',function(){
    var dark=d.getAttribute('data-theme')!=='dark';
    if(dark)d.setAttribute('data-theme','dark');else d.removeAttribute('data-theme');
    try{localStorage.setItem('site-theme',dark?'dark':'light');}catch(e){}
    label();
  });
  var f=document.querySelector('form.find');
  if(f)f.addEventListener('submit',function(e){var q=f.querySelector('input[name=q]');if(q&&!q.value.trim()){e.preventDefault();q.focus();}});
})();

  //
